// Tidies the rows read from the Watchlist tab (columns A to N). The ratios are worked out in the next node.
// If the prev_ ratio columns are formatted as percentages, '32.40%' becomes '0.3240'.
const COLS = ["ticker", "company", "sector", "business_activity", "market_cap_myr_m", "interest_bearing_debt_myr_m", "interest_bearing_deposits_myr_m", "total_revenue_myr_m", "non_permissible_income_myr_m", "shares_outstanding_m", "prev_debt_ratio", "prev_deposits_ratio", "prev_income_ratio", "prev_status"];
const frac = v => {
  const s = String(v ?? '').trim();
  if (!s.endsWith('%')) return s;
  const n = Number(s.slice(0, -1).replace(/,/g, ''));
  return Number.isFinite(n) ? (n / 100).toFixed(4) : '';
};
return $input.all().filter(i => String(i.json.ticker ?? '').trim()).map(i => {
  const r = {};
  for (const c of COLS) r[c] = String(i.json[c] ?? '');
  for (const c of ['prev_debt_ratio', 'prev_deposits_ratio', 'prev_income_ratio']) r[c] = frac(r[c]);
  return { json: r };
});

// Monthly Shariah ratio screen, ported line for line from screen.py. The numbers come from this code, never from AI.
// Limits: AAOIFI Shari'ah Standard No. 21, Financial Paper (Shares and Bonds), clause 3/4.
// "Does not exceed" means a ratio exactly at the limit passes. Change the limits here only.
const MAX_DEBT_TO_MCAP = 0.30;              // 3/4/2 interest-bearing borrowing / market capitalisation
const MAX_DEPOSITS_TO_MCAP = 0.30;          // 3/4/3 interest-taking deposits / market capitalisation
const MAX_NONPERMISSIBLE_TO_REVENUE = 0.05; // 3/4/4 prohibited income / total income
// 3/4/1 business activity is set by a person in the sheet: permissible, prohibited or review.
// 3/4/6/4 purification per share = prohibited income / number of shares.
const PASS = 'PASS', FAIL = 'FAIL', REVIEW = 'REVIEW', MISSING = 'DATA MISSING';

const toNumber = v => {
  const t = String(v ?? '').replace(/,/g, '').trim();
  if (!t) return null;
  const n = Number(t);
  return Number.isNaN(n) ? null : n;
};
const ratioScreen = (r, limit) => r === null ? MISSING : (r <= limit ? PASS : FAIL);
const businessScreen = f => {
  f = String(f ?? '').trim().toLowerCase();
  if (f === 'permissible') return PASS;
  if (f === 'prohibited') return FAIL;
  return REVIEW; // "review" or anything unexpected goes to a person
};
const safeDiv = (a, b) => (a === null || b === null || b <= 0) ? null : a / b;
const fmt = r => r === null ? '' : r.toFixed(4);
const text = v => String(v ?? '').trim();

return $input.all().map(item => {
  const row = item.json;
  const n = k => toNumber(row[k]);
  const debt = safeDiv(n('interest_bearing_debt_myr_m'), n('market_cap_myr_m'));
  const deposits = safeDiv(n('interest_bearing_deposits_myr_m'), n('market_cap_myr_m'));
  const income = safeDiv(n('non_permissible_income_myr_m'), n('total_revenue_myr_m'));
  const screens = {
    business_screen: businessScreen(row.business_activity),
    debt_screen: ratioScreen(debt, MAX_DEBT_TO_MCAP),
    deposits_screen: ratioScreen(deposits, MAX_DEPOSITS_TO_MCAP),
    income_screen: ratioScreen(income, MAX_NONPERMISSIBLE_TO_REVENUE),
  };
  const values = Object.values(screens);
  const overall = values.includes(FAIL) ? FAIL : values.includes(MISSING) ? MISSING : values.includes(REVIEW) ? REVIEW : PASS;

  const notes = [];
  const failed = Object.entries(screens).filter(([, v]) => v === FAIL).map(([k]) => k.replace('_screen', ''));
  if (failed.length) notes.push('fails: ' + failed.join(', '));
  if (values.includes(MISSING)) notes.push('missing figures, check source data');
  if (screens.business_screen === REVIEW) notes.push("business activity needs a Shariah adviser's view");

  // Not shown where the core business fails: the screen result there is to exit, not purify and hold.
  let purification = '';
  if (screens.business_screen !== FAIL) {
    const perShare = safeDiv(n('non_permissible_income_myr_m'), n('shares_outstanding_m'));
    if (perShare !== null && perShare > 0) purification = perShare.toFixed(4);
  } else {
    notes.push('purification not applicable: core business fails');
  }

  const prev = text(row.prev_status).toUpperCase();
  return { json: {
    ticker: text(row.ticker), company: text(row.company),
    debt_ratio: fmt(debt), deposits_ratio: fmt(deposits), income_ratio: fmt(income),
    prev_debt_ratio: text(row.prev_debt_ratio), prev_deposits_ratio: text(row.prev_deposits_ratio),
    prev_income_ratio: text(row.prev_income_ratio),
    ...screens,
    overall_status: overall, prev_status: prev,
    status_changed: prev && prev !== overall ? 'YES' : 'NO',
    purification_per_share_myr: purification,
    notes: notes.join('; '),
  }};
});

// Keeps only the shares whose overall status changed since last month, as one item for one Claude call.
// If nothing changed, it returns nothing, so no Claude call and no email.
const pct = v => (v === '' || v === null || v === undefined || Number.isNaN(Number(v))) ? 'n/a' : (Number(v) * 100).toFixed(2) + '%';
const changed = $input.all().map(i => i.json).filter(r => r.status_changed === 'YES');
if (!changed.length) return [];
const shares = changed.map(r => ({
  ticker: r.ticker, company: r.company, prev_status: r.prev_status, status: r.overall_status,
  business_screen: r.business_screen,
  debt_now: pct(r.debt_ratio), debt_prev: pct(r.prev_debt_ratio),
  deposits_now: pct(r.deposits_ratio), deposits_prev: pct(r.prev_deposits_ratio),
  income_now: pct(r.income_ratio), income_prev: pct(r.prev_income_ratio),
  raw: { debt: [r.prev_debt_ratio, r.debt_ratio], deposits: [r.prev_deposits_ratio, r.deposits_ratio],
         income: [r.prev_income_ratio, r.income_ratio] },
}));
const lines = shares.map(s =>
  `ticker=${s.ticker}, company=${s.company}, status last month=${s.prev_status}, status now=${s.status}, ` +
  `debt ratio now=${s.debt_now} (last month ${s.debt_prev}), deposits ratio now=${s.deposits_now} (last month ${s.deposits_prev}), ` +
  `income ratio now=${s.income_now} (last month ${s.income_prev}), business activity screen=${s.business_screen}`);
return [{ json: { count: shares.length, shares, text: lines.join('\n') } }];

// Builds the Claude request: the prompt from the README, with this month's changed shares at the end.
const PROMPT = "You are helping the admin of a small family investment club write a monthly Shariah screening note. The shares below changed screening status since last month. Every ratio, limit and status was computed by a spreadsheet formula before you saw it.\n\nScreens and limits (AAOIFI Shari'ah Standard No. 21, clause 3/4): interest-bearing debt up to 30% of market capitalisation; interest-bearing deposits up to 30% of market capitalisation; non-permissible income up to 5% of total revenue; business activity must be permissible.\n\nFor each share, write two or three short, plain-English sentences saying which screen or screens caused the change. Quote this month's ratio, last month's ratio and the limit exactly as given.\n\nRules:\n1. Use only the numbers given. Do not recalculate, re-round, estimate or add any number.\n2. Do not change or contradict any status. If the data looks inconsistent, write 'figures need checking' and set needs_human_check to true.\n3. Do not say why the company's figures moved (for example, new borrowing) unless the data says so. If the cause is not in the data, say the figures alone do not show why.\n4. Do not give a Shariah ruling, a fatwa, or a buy, sell or hold recommendation.\n5. Plain British English. No em dashes.\n\nShares: ";
const SCHEMA = {
 "type": "object",
 "properties": {
  "explanations": {
   "type": "array",
   "items": {
    "type": "object",
    "properties": {
     "ticker": {
      "type": "string"
     },
     "screens_that_changed": {
      "type": "array",
      "items": {
       "type": "string",
       "enum": [
        "debt",
        "deposits",
        "income",
        "business_activity"
       ]
      }
     },
     "explanation": {
      "type": "string"
     },
     "needs_human_check": {
      "type": "boolean"
     }
    },
    "required": [
     "ticker",
     "screens_that_changed",
     "explanation",
     "needs_human_check"
    ],
    "additionalProperties": false
   }
  }
 },
 "required": [
  "explanations"
 ],
 "additionalProperties": false
};
const d = $input.first().json;
return [{ json: {
  output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
  messages: [{ role: 'user', content: PROMPT + d.text }],
} }];

// Reads Claude's reply from the content block whose type is "text".
// It is used only when stop_reason is end_turn and the text parses as JSON. Otherwise the admin writes the notes by hand.
const r = $input.first().json;
const stop = r.stop_reason || 'no reply';
const block = (Array.isArray(r.content) ? r.content : []).find(b => b.type === 'text');
let parsed = null, problem = '';
if (r.error) problem = 'API error: ' + (r.error.message || JSON.stringify(r.error));
else if (stop !== 'end_turn') problem = 'stop reason ' + stop;
else if (!block) problem = 'no text block in the reply';
else { try { parsed = JSON.parse(block.text); } catch (e) { problem = 'the reply was not valid JSON'; } }
if (!parsed || !Array.isArray(parsed.explanations)) {
  return [{ json: { aiOk: false, problem: problem || 'reply did not match the schema', explanations: [] } }];
}
return [{ json: { aiOk: true, ...parsed } }];

// Code check on the explanations. Every percentage quoted must be one of the computed numbers for that share
// (this month, last month, or the 30% and 5% limits), and the screens named must match the ratios.
const LIMITS = { debt: 0.30, deposits: 0.30, income: 0.05 };
const reply = $input.first().json;
const shares = $('Changed shares only').first().json.shares;
const aiOk = reply.aiOk !== false;
const byTicker = {};
for (const e of (reply.explanations || [])) byTicker[String(e.ticker).trim().toUpperCase()] = e;
const two = s => { const n = parseFloat(String(s).replace('%', '')); return Number.isNaN(n) ? null : n.toFixed(2); };

const out = shares.map(s => {
  const e = byTicker[s.ticker];
  delete byTicker[s.ticker];
  const problems = [];
  let quoted = [];
  if (!aiOk) problems.push('No explanation was drafted (' + reply.problem + '). Please write this note by hand');
  else if (!e) problems.push('No explanation came back for this share');
  if (e) {
    const allowed = new Set(['30.00', '5.00', ...[s.debt_now, s.debt_prev, s.deposits_now, s.deposits_prev, s.income_now, s.income_prev].map(two)].filter(Boolean));
    quoted = [...String(e.explanation).matchAll(/(\d+(?:\.\d+)?)\s*%/g)].map(m => m[1] + '%');
    const unmatched = quoted.filter(q => !allowed.has(two(q)));
    if (unmatched.length) problems.push('Figures quoted that are not in the computed numbers: ' + unmatched.join(', '));
    const computed = Object.keys(LIMITS).filter(k => {
      const [prev, now] = s.raw[k];
      if (prev === '' || now === '' || prev == null || now == null) return false;
      return (Number(prev) <= LIMITS[k]) !== (Number(now) <= LIMITS[k]);
    });
    const named = (e.screens_that_changed || []).filter(x => x !== 'business_activity');
    if ([...named].sort().join(',') !== [...computed].sort().join(',')) {
      problems.push('Screens named (' + (named.join(', ') || 'none') + ') do not match the ratios (' + (computed.join(', ') || 'none') + ')');
    }
    if (e.needs_human_check) problems.push('The draft itself asks for a person to check the figures');
  }
  return { json: { ticker: s.ticker, company: s.company, prev_status: s.prev_status, status: s.status,
    explanation: e ? String(e.explanation) : '', quoted: quoted.join(', '),
    check: problems.length ? 'CHECK' : 'OK', problems: problems.join('; ') } };
});
for (const t of Object.keys(byTicker)) {
  out.push({ json: { ticker: t, company: '', prev_status: '', status: '', explanation: String(byTicker[t].explanation), quoted: '',
    check: 'CHECK', problems: 'Explanation for a share whose status did not change' } });
}
return out;

// Builds the admin's monthly report. The table comes from the screen node, never from the AI text.
const WINE = '#4a1424', RED = '#b3202a', INK = '#1d1416', MUTED = '#5f5456', LINE = '#d9d4d5';
const rows = $('Screen ratios (AAOIFI SS 21)').all().map(i => i.json);
const notes = $input.all().map(i => i.json);
if (!notes.length) return [];
const pct = v => v === '' ? 'n/a' : (Number(v) * 100).toFixed(2) + '%';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const th = 'text-align:left;padding:7px 8px;background:' + WINE + ';color:#ffffff;border:1px solid ' + WINE + ';font-weight:bold';
const td = 'padding:7px 8px;border:1px solid ' + LINE;
const heads = ['Ticker', 'Company', 'Debt / mcap', 'Deposits / mcap', 'Non-perm. income / revenue', 'Business', 'Status', 'Last month', 'Changed', 'Purification per share (MYR)'];
const table = '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:13px;width:100%">' +
  '<tr>' + heads.map(h => '<th style="' + th + '">' + h + '</th>').join('') + '</tr>' +
  rows.map(r => '<tr>' + [
    '<b>' + esc(r.ticker) + '</b>', esc(r.company), pct(r.debt_ratio), pct(r.deposits_ratio), pct(r.income_ratio),
    r.business_screen, '<b style="color:' + (r.overall_status === 'PASS' ? INK : RED) + '">' + r.overall_status + '</b>',
    r.prev_status, r.status_changed === 'YES' ? '<b>Yes</b>' : '', r.purification_per_share_myr || 'n/a',
  ].map(c => '<td style="' + td + '">' + c + '</td>').join('') + '</tr>').join('') + '</table>';
const flagged = notes.filter(n => n.check !== 'OK').length;
const changes = notes.map(n =>
  '<div style="border:1px solid ' + LINE + ';padding:12px 14px;margin:0 0 10px">' +
  '<div style="font-weight:bold;color:' + WINE + ';margin:0 0 4px">' + esc(n.ticker) + ' ' + esc(n.company) +
  (n.prev_status ? ': ' + n.prev_status + ' to ' + n.status : '') + '</div>' +
  (n.explanation ? '<div>' + esc(n.explanation) + '</div>' : '') +
  (n.check === 'OK'
    ? '<div style="font-size:12px;color:' + MUTED + ';margin-top:6px">Code check: every figure quoted matches the table.</div>'
    : '<div style="color:' + RED + ';font-weight:bold;margin-top:6px">Check before sharing: ' + esc(n.problems) + '</div>') +
  '</div>').join('');
const month = new Date().toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
const html =
  '<div style="font-family:Helvetica,Arial,sans-serif;color:' + INK + ';max-width:880px;margin:0 auto;border:1px solid ' + LINE + '">' +
  '<div style="background:' + WINE + ';color:#ffffff;padding:20px 26px"><div style="font-family:Georgia,serif;font-size:19px;letter-spacing:2px">AL-NOOR FAMILY INVESTMENT CLUB</div>' +
  '<div style="width:48px;height:2px;background:' + RED + ';margin-top:8px"></div></div>' +
  '<div style="padding:22px 26px"><h1 style="font-family:Georgia,serif;color:' + WINE + ';font-size:23px;margin:0 0 6px">Monthly Shariah screen</h1>' +
  '<p style="margin:0 0 18px;color:' + MUTED + '">For the club admin. Please review this with the club\'s Shariah adviser before sharing it with members.</p>' +
  '<p style="font-size:13px;color:' + RED + ';margin:0 0 8px;font-weight:bold;letter-spacing:1px">WHAT CHANGED (' + notes.length + ')</p>' + changes +
  '<p style="font-size:13px;color:' + RED + ';margin:20px 0 8px;font-weight:bold;letter-spacing:1px">FULL WATCHLIST</p>' + table + '</div>' +
  '<div style="border-top:1px solid ' + LINE + ';padding:14px 26px;font-size:12px;color:' + MUTED + '">' +
  'Ratios, statuses and purification amounts are worked out by code that mirrors screen.py. Limits follow AAOIFI Shari\'ah Standard No. 21, clause 3/4: ' +
  'interest-bearing debt and deposits up to 30% of market capitalisation each, non-permissible income up to 5% of total revenue. ' +
  'The short explanations are drafted from those numbers only, and code checks every percentage they quote against the table. ' +
  'This report is for education and club discussion. It is not a fatwa or investment advice. ' +
  'Al-Noor Family Investment Club (a fictional organisation).</div></div>';
return [{ json: { to: 'admin@example.org',
  subject: 'Monthly Shariah screen: ' + notes.length + ' status change' + (notes.length === 1 ? '' : 's') + ' for review (' + month + ')' + (flagged ? ', ' + flagged + ' to check' : ''),
  changes: notes.length, flagged, html } }];
